public class SolutionTest {
    public static void main(String[] args) {
        Solution.Rectangle content = new Solution.Rectangle(0, 0, 10, 8);
        Solution.Rectangle viewport = new Solution.Rectangle(4, 3, 10, 10);
        Solution.Rectangle overlap = Solution.visibleRegion(content, viewport);
        rectangle(overlap, 4, 3, 6, 5, "overlap");
        check(overlap != content && overlap != viewport, "new rectangle");
        rectangle(content, 0, 0, 10, 8, "content unchanged");
        rectangle(viewport, 4, 3, 10, 10, "viewport unchanged");

        rectangle(Solution.visibleRegion(
                new Solution.Rectangle(0, 0, 2, 2),
                new Solution.Rectangle(2, 1, 3, 3)), 2, 1, 0, 1, "edge touching");
        rectangle(Solution.visibleRegion(
                new Solution.Rectangle(0, 0, 2, 2),
                new Solution.Rectangle(2, 2, 3, 3)), 2, 2, 0, 0, "point touching");
        rectangle(Solution.visibleRegion(
                new Solution.Rectangle(0, 0, 2, 2),
                new Solution.Rectangle(5, 7, 1, 1)), 5, 7, 0, 0, "disjoint clamped origin");
        rectangle(Solution.visibleRegion(
                new Solution.Rectangle(5, 7, 0, 0),
                new Solution.Rectangle(0, 0, 10, 10)), 5, 7, 0, 0, "empty content");

        Solution.Rectangle extremeLeft = new Solution.Rectangle(Integer.MIN_VALUE, -1, Integer.MAX_VALUE, 2);
        Solution.Rectangle nearLeft = new Solution.Rectangle(-2, -2, 4, 4);
        rectangle(Solution.visibleRegion(extremeLeft, nearLeft), -2, -1, 1, 2, "extreme valid bounds");
        Solution.Rectangle maxPoint = new Solution.Rectangle(Integer.MAX_VALUE, Integer.MAX_VALUE, 0, 0);
        rectangle(Solution.visibleRegion(maxPoint, maxPoint), Integer.MAX_VALUE, Integer.MAX_VALUE, 0, 0, "max empty point");

        expectIllegal(new Action() { public void run() { Solution.visibleRegion(null, content); } });
        expectIllegal(new Action() { public void run() { Solution.visibleRegion(content, null); } });
        expectIllegal(new Action() { public void run() { new Solution.Rectangle(0, 0, -1, 0); } });
        expectIllegal(new Action() { public void run() { new Solution.Rectangle(0, 0, 0, -1); } });
        expectIllegal(new Action() { public void run() { new Solution.Rectangle(Integer.MAX_VALUE, 0, 1, 0); } });
        expectIllegal(new Action() { public void run() { new Solution.Rectangle(0, Integer.MAX_VALUE, 0, 1); } });
    }

    private interface Action { void run(); }
    private static void expectIllegal(Action action) {
        try { action.run(); throw new AssertionError("Expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }
    private static void rectangle(Solution.Rectangle value, int x, int y, int width, int height, String message) {
        if (value == null || value.x != x || value.y != y || value.width != width || value.height != height) {
            throw new AssertionError(message + ": expected (" + x + "," + y + "," + width + "," + height
                    + ") but got " + (value == null ? "null" : "(" + value.x + "," + value.y + "," + value.width + "," + value.height + ")"));
        }
    }
    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

